SELECT city_group, signup_month, avg_credit_limit FROM (SELECT CASE WHEN city IN ('Berlin', 'Singapore') THEN 'priority' ELSE 'other' END AS city_group, DATE_TRUNC('MONTH', signup_date) AS signup_month, ROUND(AVG(credit_limit), 2) AS avg_credit_limit FROM customers GROUP BY CASE WHEN city IN ('Berlin', 'Singapore') THEN 'priority' ELSE 'other' END, DATE_TRUNC('MONTH', signup_date)) AS agg WHERE avg_credit_limit < 80 ORDER BY city_group DESC;
